const he = require('he');

// 创建一个空数组，用于存放处理后的结果
const newItems = [];

// 遍历 n8n 节点收到的每一个 item
for (const item of items) {
    // 1. 创建一个当前 item 的深拷贝副本，这是一个非常安全的做法
    const newItem = JSON.parse(JSON.stringify(item));

    // 2. 在副本上进行解码操作
    // 检查并解码 content 字段
    if (newItem.json.content && typeof newItem.json.content === 'string') {
        newItem.json.content = he.decode(newItem.json.content);
    }

    // 检查并解码 title 字段
    if (newItem.json.title && typeof newItem.json.title === 'string') {
        newItem.json.title = he.decode(newItem.json.title);
    }

    // 3. 将处理完毕的副本推入新的结果数组
    newItems.push(newItem);
}

// 4. 返回全新的、包含了解码后内容的结果数组
return newItems;

// 获取上一个节点（HTTP Request）返回的HTML内容
const html = $input.item.json.data;

// 使用正则表达式查找docHtmlCon变量的内容
// 这个表达式会匹配 "docHtmlCon": "..." 直到下一个 "," 和 "abstract" 为止
const regex = /"docHtmlCon":\s*"(.*?)"\s*,\s*"abstract"/s;
const match = html.match(regex);

// 检查是否成功匹配
if (match && match[1]) {
  // 匹配到的内容在第二个捕获组 (match[1])
  let content = match[1];

  // JavaScript字符串中的 \" 需要转回 "
  content = content.replace(/\\"/g, '"');

  // 将提取到的干净的HTML内容作为新字段返回
  $input.item.json.articleContent = content;

} else {
  // 如果没找到，返回一个错误提示
  $input.item.json.error = "无法在HTML中找到文章内容";
}

// 返回处理后的数据项，以便下一个节点使用
return $input.item;
